import numpy as np
import ctypes, os
_lib=ctypes.CDLL(os.path.join(os.path.dirname(__file__),'auction.so'))
_lib.assign.argtypes=[ctypes.POINTER(ctypes.c_double),ctypes.c_int,ctypes.POINTER(ctypes.c_int)]
class Solver:
 def solve(self,problem,**kwargs):
